"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1558],{1558:a=>{a.exports=JSON.parse('{"slug":"inflyaciya-oktyabr-2026-tarify-zhkh","locale":"ru","title":"Годовая инфляция за неделю выросла с 6,26% до 7,17% после индексации тарифов ЖКХ","description":"С 29 сентября по 5 октября 2026 года цены выросли на 0,96%, годовая инфляция 7,17%. Сколько дали тарифы ЖКХ и почему годовой показатель прыгнул за неделю.","blocks":[{"id":"b001","kind":"paragraph","text":"С 29 сентября по 5 октября 2026 года потребительские цены в России выросли на 0,96%, неделей раньше на 0,12%. Индексация тарифов ЖКХ с 1 октября дала 0,75 процентного пункта из этого роста. Водоотведение подорожало на 17,1%, холодная вода на 15,3%, горячая на 14,2%, отопление на 12,7%, электроэнергия на 12%. Всю плату за коммунальные услуги проиндексировали меньше, в среднем по стране на 9,9%: этот индекс правительство задаёт для суммы платежа, а не для каждой услуги. В Москве он до 15%, в Петербурге до 14,6%, выше всего в Ставропольском крае, до 22%."},{"id":"b002","kind":"paragraph","text":"Без ЖКХ цены за неделю выросли на 0,21%. Это быстрее, чем неделей раньше росла вся корзина. Продукты подорожали на 0,17%: плодоовощи подешевели на 0,57%, остальное подорожало на 0,24%. Яйца выросли в цене на 2,2%, мясные консервы на 1,6%, гречка на 1%. Непродовольственные товары прибавили 0,13%, смартфоны 1,1%, телевизоры 1%."},{"id":"b003","kind":"paragraph","text":"Годовая инфляция за неделю выросла с 6,26% до 7,17%. Представим семью, которая раз в год платит за страховку машины: в прошлом году в июле, в этом в октябре. В октябре её расходы рядом с прошлогодними кажутся выросшими, хотя за год сумма та же. С тарифами так же: в 2025 году их подняли 1 июля на 11,9%, в 2026-м на 1,7% в январе и на 9,9% в октябре, вместе примерно на 11,8%. В октябре 2025 года тарифы не менялись, поэтому весь нынешний скачок ушёл в годовую цифру. Это называют эффектом базы. С 2027 года тарифы снова будут повышать в июле."},{"id":"b004","kind":"paragraph","text":"Если коммунальные услуги в квитанции стоили 6 тыс. рублей в месяц, они подорожали в среднем примерно на 600 рублей, в Москве до 900. Плата за содержание дома и капремонт в эту индексацию не входит. Отложить этот расход нельзя. Вклады пока обгоняют рост цен: средняя максимальная ставка в 10 крупнейших банках в конце сентября была 13,05%, а годовая инфляция 7,17%."},{"id":"b005","kind":"paragraph","text":"Банк России ждёт инфляцию в 2026 году на уровне 6–7%. С начала года цены выросли на 5,94%, а годовая инфляция по методике регулятора, 7,08%, уже выше верхней границы прогноза на конец года. Вклад индексации, около 0,7 пункта, советник председателя Банка России Кирилл Тремасов назвал ещё в сентябре, поэтому для решения по ставке 23 октября важнее остальные цены. Темп 0,21% в неделю, если бы он держался весь год, дал бы больше 11%. 11 сентября Банк России сохранил ставку 14% и предупредил, что риски ускорения инфляции перевешивают."},{"id":"b006","kind":"paragraph","text":"Одна неделя мало что доказывает. Месячные данные за сентябрь Росстат публикует 9 октября, следующие недельные 14 октября. Если без тарифов рост вернётся к 0,1% в неделю, скачок окажется разовым. Если удержится около 0,2%, у Банка России будет меньше поводов снижать ставку, и кредиты дольше останутся дорогими, а вклады доходными."},{"id":"b007","kind":"heading","text":"Почему инфляция в начале октября 2026 года выросла до 0,96% за неделю?"},{"id":"b008","kind":"paragraph","text":"С 1 октября проиндексировали тарифы ЖКХ, в среднем на 9,9%. Это дало 0,75 процентного пункта из 0,96%. Без ЖКХ цены за неделю выросли на 0,21%."},{"id":"b009","kind":"heading","text":"Почему годовая инфляция за неделю подскочила с 6,26% до 7,17%?"},{"id":"b010","kind":"paragraph","text":"Из-за эффекта базы. В 2025 году тарифы ЖКХ повысили 1 июля на 11,9%, а в 2026-м на 1,7% в январе и на 9,9% с 1 октября. В октябре 2025 года тарифы не менялись, поэтому сравнение с прошлым годом резко подняло годовую цифру, хотя за год тарифы вырастут почти так же, примерно на 11,8%."},{"id":"b011","kind":"heading","text":"Насколько выросли платежи за ЖКХ с 1 октября 2026 года?"},{"id":"b012","kind":"paragraph","text":"Плата за коммунальные услуги в среднем по стране выросла на 9,9%, в Москве до 15%, в Петербурге до 14,6%, в Ставропольском крае до 22%. Содержание дома и капремонт сюда не входят. По отдельным услугам за неделю водоотведение подорожало на 17,1%, холодная вода на 15,3%, отопление на 12,7%, электроэнергия на 12%."}],"sources":[{"label":"Инфляция в России с 29 сентября по 5 октября","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Минэк оценил вклад индексации тарифов ЖКХ в недельную инфляцию в 0,75 п. п.","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235205-minek-otsenil-vklad-indeksatsii"},{"label":"Вклад индексации тарифов ЖКХ в недельную инфляцию оценен в 0,75 п.п.","url":"https://www.interfax.ru/business/1120937"},{"label":"МЭР: годовая инфляция в России с 29 сентября по 5 октября составила 7,17%","url":"https://www.bfm.ru/news/620178"},{"label":"Тарифы ЖКХ с 1 октября 2026 года, как изменятся платежи","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_tarify-zhkkh-s-1-oktyabrya-2026-goda-kak-izmenyatsya-platezhi"},{"label":"Недельная инфляция в РФ подскочила на 0,96% из-за индексации тарифов","url":"https://ru.themoscowtimes.com/2026/10/07/nedelnaya-inflyatsiya-v-rf-podskochila-na-096-iz-za-indeksatsii-tarifov-a208051"},{"label":"Банк России повысил прогноз по инфляции на 2026 год","url":"https://www.kommersant.ru/doc/8843971"},{"label":"Ключевая ставка ЦБ 11 сентября 2026 сохранена на 14%","url":"https://finance.mail.ru/article/stavka-centrobanka-neizmenna-14-kak-reshenie-soveta-direktorov-cb-povliyaet-na-ekonomiku-69227357/"},{"label":"Средняя максимальная ставка по вкладам десяти банков выросла до 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"}],"sourceBodySha256":"2123f3266d3346c5a40c0ca0051d02fcbfdc4a0c1b55fe5c397edea22f975b4d"}')}}]);